mapper.select:
SELECT kd.id, su.user_name, so.org_name, kd.commission, kd.create_time, kd.service_code, kd.service_name, kd.service_type, kd.item_type, kd.performance FROM kpi_detail kd LEFT JOIN sys_user su ON kd.user_id = su.id LEFT JOIN sys_org so ON su.org_id = so.id
AND su.username LIKE CONCAT('%', #{query.username}, '%')
AND su.org_id = #{query.orgId}
AND kd.create_time >= #{query.beginDate}
AND kd.create_time <= CONCAT(#{query.endDate}, ' 23:59:59')
ORDER BY kd.create_time DESC
